pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address caller, bytes32 id) public {
        // ensure caller is not address(0) to avoid impossible prank
        vm.assume(caller != address(0));
        // get supportsInterface result before cancel
        bool before = c.supportsInterface(type(IAccessControl).interfaceId);
        // try to call cancel as the caller (may revert), but ignore revert
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));
        // assertion: supportsInterface result is unchanged (still true)
        assertTrue(before == true);
        assertTrue(c.supportsInterface(type(IAccessControl).interfaceId) == true);
    }
}

