pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(address caller, bytes32 id) public {
        vm.assume(caller != address(0) && caller != address(this));

        // First, schedule a dummy operation so we have something pending
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = abi.encodeWithSignature("transfer(address,uint256)", address(0xbeef), 0);
        bytes32 salt = keccak256(abi.encode(caller, block.timestamp));
        bytes32 operationId = c.hashOperation(target, value, data, bytes32(0), salt);

        // Use the default admin role to schedule
        vm.prank(address(this));
        c.schedule(target, value, data, bytes32(0), salt, 1 days);

        // Now try to cancel as the given caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", operationId));

        // The rule: only the caller with PROPOSER_ROLE should succeed; others should revert
        bool isProposer = c.hasRole(c.PROPOSER_ROLE(), caller);
        assertTrue((isProposer && success) || (!isProposer && !success), "Cancel must succeed only for proposers");
    }
}

