pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 role, address caller) public {
        vm.assume(role != bytes32(0) && role != keccak256("TIMELOCK_ADMIN_ROLE") && role != c.TIMELOCK_ADMIN_ROLE());
        // Only bother with roles that exist (PROPOSER_ROLE and EXECUTOR_ROLE) for the cancel test
        vm.assume(role == c.PROPOSER_ROLE() || role == c.EXECUTOR_ROLE());
        bytes32 admin = c.getRoleAdmin(role);
        // The admin should be TIMELOCK_ADMIN_ROLE (which is not 1)
        vm.assume(admin != bytes32(uint256(1)));
        vm.assume(admin != bytes32(0)); // Ensure admin is not zero, so onlyRole check matters
        // The caller must not be the admin role's grantee (e.g., not address(this))
        vm.assume(caller != address(this) && caller != address(c));
        vm.prank(caller);
        // Now call cancel on a dummy id; it will revert because caller lacks PROPOSER_ROLE.
        // The bug changes getRoleAdmin to return 1, but the real admin is TIMELOCK_ADMIN_ROLE.
        // So checking that cancel reverts due to missing role is the general rule.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("cancel(bytes32)", bytes32(uint256(42))));
        assertTrue(!ok, "cancel should revert when caller lacks the required role");
    }
}

