pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the operation is not already scheduled (getTimestamp returns 0)
        require(c.getTimestamp(id) == 0, "operation already scheduled");
        // Grant PROPOSER_ROLE to this contract to call cancel
        vm.prank(address(this));
        c.grantRole(c.PROPOSER_ROLE(), address(this));
        // Cancel the unscheduled operation; it should revert because isOperationPending(id) will be false
        vm.prank(address(this));
        (bool ok, ) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));
        // After the call (regardless of revert), the operation's timestamp should remain 0
        // The key rule: isOperation(id) should return false because timestamp is 0 (not > 0)
        // In the buggy version, isOperation returns true for any id since getTimestamp(id) >= 0 is always true
        // In the reference, isOperation returns false
        // We assert that the result matches the reference behavior
        assertTrue(c.isOperation(id) == false, "isOperation should be false for unscheduled operation");
    }
}

