// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Bound id to avoid collisions with real scheduled operations; just use any id
        vm.assume(id != bytes32(0));

        // Set the timestamp directly by scheduling and then manipulating block.timestamp
        // We need to schedule an operation so it has a timestamp
        address target = address(0xdead);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = id;
        uint256 delay = 1;

        // Only proceed if we are a proposer
        c.grantRole(c.PROPOSER_ROLE(), address(this));

        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);

        // Now fast forward to exactly the scheduled time so timestamp == block.timestamp
        // The operation should be ready in P but not in M
        vm.warp(block.timestamp + delay);

        // In P: isOperationReady should return true because timestamp <= block.timestamp
        // In M: isOperationReady should return false because timestamp < block.timestamp is false
        bool ready = c.isOperationReady(c.hashOperation(target, value, data, predecessor, salt));

        // Cancel the operation to test the cancel function
        // In P: cancel should succeed because isOperationReady returns true (operation is ready)
        // In M: cancel should fail because isOperationReady returns false (operation not ready)
        // Actually cancel requires isOperationPending, not isOperationReady. Let's check isOperationPending
        // In both: isOperationPending should be true (timestamp > _DONE_TIMESTAMP)
        bool pending = c.isOperationPending(c.hashOperation(target, value, data, predecessor, salt));
