import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(bytes32 id) public {
        // Ensure the id corresponds to a scheduled operation that can be cancelled
        // We simulate scheduling by calling a schedule-like path through the contract
        // But since schedule() checks PROPOSER_ROLE, we use the deployer who has it
        vm.assume(id != bytes32(0));
        // We need to make sure the operation is pending: schedule it
        // Use arbitrary target, value, data, predecessor, salt, and delay
        address target = address(0x1234);
        uint256 value = 0;
        bytes memory data = "";
        bytes32 predecessor = bytes32(0);
        bytes32 salt = bytes32(0);
        uint256 delay = 1;
        // Schedule the operation
        c.schedule(target, value, data, predecessor, salt, delay);
        // Compute the operation id from the same parameters
        bytes32 opId = c.hashOperation(target, value, data, predecessor, salt);
        // Ensure the operation is pending and not ready (block.timestamp < scheduled time)
        assertTrue(c.isOperationPending(opId));
        // Cancel the operation
        c.cancel(opId);
        // After cancel, isOperationDone should be false
        assertTrue(!c.isOperationDone(opId));
    }
}

