pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 offset) public {
        // Ensure delay is at least minDelay (0)
        uint256 delay = bound(offset, 0, 1000000);

        // Schedule an operation
        c.schedule(target, value, data, predecessor, salt, delay);
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);

        // Warp to after the delay so operation is ready
        vm.warp(block.timestamp + delay + 1);

        // Execute the operation (we have EXECUTOR_ROLE via address(this))
        c.execute(target, value, data, predecessor, salt);

        // Now the operation should be done: getTimestamp(id) == _DONE_TIMESTAMP (1)
        // The mutated version would return block.timestamp instead
        uint256 ts = c.getTimestamp(id);
        // In reference P: after execution, timestamp is always 1 (done)
        // In mutant M: timestamp = block.timestamp, which is > 1
        // General rule: after execution, timestamp is exactly 1 (or <= some constant)
        assertTrue(ts == 1, "getTimestamp should return DONE_TIMESTAMP after execution");
    }
}

