pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }
    function testFuzz_property(address target, uint256 value, bytes memory data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        // Bound delay to avoid underflow
        vm.assume(delay >= c.getMinDelay() && delay <= 1000000);
        // Bound target to avoid low-level revert (allow any address)
        vm.assume(target != address(0));
        bytes32 id = c.hashOperation(target, value, data, predecessor, salt);
        c.schedule(target, value, data, predecessor, salt, delay);
        // Fast-forward past the delay
        vm.warp(block.timestamp + delay + 1);
        // Execute the operation (need executor role)
        vm.prank(address(this));
        c.execute{value: value}(target, value, data, predecessor, salt);
        // Now cancel should fail because operation is done
        // The rule: after execution, cancel reverts
        vm.expectRevert();
        c.cancel(id);
    }
}

