pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, address(this), address(this)); }

    function testFuzz_property(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata datas,
        bytes32 predecessor,
        bytes32 salt,
        uint256 delay
    ) public {
        delay = bound(delay, 0, 100 days);
        vm.assume(targets.length == values.length && targets.length == datas.length);
        vm.assume(targets.length > 0 && targets.length <= 10);

        // Use a proper delay to schedule the operation
        c.scheduleBatch(targets, values, datas, predecessor, salt, delay);

        bytes32 id = c.hashOperationBatch(targets, values, datas, predecessor, salt);
        bytes32 idChecked = c.hashOperationBatch(targets, values, datas, predecessor, salt);

        // Try to cancel immediately; it should revert because operation is not pending (scheduled with delay > 0? Actually delay is 0?)
        // The reference will revert because operation is not pending.
        // The mutant may produce a different id, so cancel might succeed instead of revert.
        (bool canceled, bytes memory revertData) = address(c).call(abi.encodeWithSelector(c.cancel.selector, id));

        // Now compute the hash with the incorrect encoding order
        bytes32 wrongId = keccak256(abi.encode(salt, predecessor, datas, values, targets));
        bool isActuallyCancellable = c.isOperationPending(id) || c.isOperationDone(id);

        // The property: cancel should revert if the operation is not pending
        // For the reference, cancel always uses the correct hash, so it reverts if not pending.
        // For the mutant, cancel uses the same correct hash (since cancel doesn't call hashOperationBatch), so also reverts.
        // Actually we need a difference. Let's try a different approach: ensure the mutant's hash is used in schedule.
        // Let's use a scenario where the mutant would schedule a different operation.
    }

    function testFuzz_property2(
        address[] calldata targets,
        uint256[] calldata values,
        bytes[] calldata datas,
        bytes32 predecessor,
        bytes32 salt
    ) public {
        vm.assume(targets.length == values.length && targets.length == datas.length);
        vm.assume(targets.length > 0 && targets.length <= 5);

        // Compute the hash as the reference would
        bytes32 expectedId = keccak256(abi.encode(targets, values, datas, predecessor, salt));
        // Compute the hash as the mutant would
        bytes32 mutantId = keccak256(abi.encode(salt, predecessor, datas, values, targets));

        // The property: the hash returned by the contract should equal the reference hash
        bytes32 actualId = c.hashOperationBatch(targets, values, datas, predecessor, salt);

        // For the reference contract, actualId == expectedId always.
        // For the mutant, actualId == mutantId != expectedId.
        assertTrue(actualId == expectedId, "Hash must match reference encoding");
    }
}

